CREATE TABLE IF NOT EXISTS opportunity_assessments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid NOT NULL REFERENCES assets(id) ON DELETE CASCADE, opportunity_type text NOT NULL, thesis text, estimated_capital_required numeric(20,2), currency text NOT NULL DEFAULT 'NGN', development_horizon_months integer, expected_impact text, assumptions jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'draft', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());